// Extract and validate lead data from webhook
const body = $input.first().json.body || $input.first().json;

const leadName = body.lead_name || body.name || 'there';
const phoneNumber = body.phone_number || body.phone || '';
const leadSource = body.lead_source || 'Unknown';
const courseInterest = body.course_interest || 'Unknown';
const leadId = body.lead_id || body.id || Date.now().toString();

// Validate phone number - must be 10 digits Indian number
const cleanPhone = phoneNumber.replace(/[^0-9]/g, '');
const isValidPhone = cleanPhone.length === 10 || 
                     (cleanPhone.length === 12 && cleanPhone.startsWith('91'));

if (!isValidPhone) {
  throw new Error(`Invalid phone number: ${phoneNumber}`);
}

// Format for Exotel - needs 0XXXXXXXXXX format
const exotelPhone = cleanPhone.length === 10 ? 
  '0' + cleanPhone : 
  '0' + cleanPhone.slice(2);

return [{
  json: {
    leadId,
    leadName,
    phoneNumber: cleanPhone,
    exotelPhone,
    leadSource,
    courseInterest,
    callStartTime: new Date().toISOString(),
    conversationHistory: [],
    callStatus: 'initiated'
  }
}];

// Store call SID and lead data for the ongoing conversation
const exotelResponse = $input.first().json;
const leadData = $('Prepare & Validate Lead Data').first().json;

const callSid = exotelResponse.Call?.Sid || exotelResponse.Sid || 'unknown';

return [{
  json: {
    ...leadData,
    callSid,
    callInitiated: true,
    exotelResponse
  }
}];

// Build conversation history and prepare GPT messages
const sttResult = $input.first().json;
const callHandlerData = $('Call Handler Webhook (Exotel Streams Here)').first().json;

// Get transcribed text from Sarvam
const userTranscript = sttResult.transcript || 
                       sttResult.text || 
                       callHandlerData.body?.speech_result || 
                       '';

// Get stored conversation history (passed via Exotel CustomField or stored in memory)
let conversationHistory = [];
try {
  const historyRaw = callHandlerData.body?.conversation_history || '[]';
  conversationHistory = JSON.parse(historyRaw);
} catch(e) {
  conversationHistory = [];
}

// Get lead context
const leadName = callHandlerData.body?.lead_name || 'there';
const courseInterest = callHandlerData.body?.course_interest || 'Unknown';

// Add new user message to history
if (userTranscript) {
  conversationHistory.push({
    role: 'user',
    content: userTranscript
  });
}

// Build the full system prompt with lead context injected
const systemPrompt = `You are PRIYA, a warm outbound sales agent for Social Eagle Academy.

LEAD CONTEXT FOR THIS CALL:
- Lead Name: ${leadName}
- Known Course Interest: ${courseInterest}
- Call started at: ${new Date().toISOString()}

LANGUAGE: Always speak natural Tanglish (Tamil + English mix). Never full Tamil, never full English.

YOUR GOAL: Qualify the lead, build rapport, pitch the right course, and book a Zoom meeting. Collect: name confirmation, phone confirmation, course interest, current situation (job/business/student), preferred meeting day and time.

COURSES:
1. Digital Entrepreneurship Program (DEP) - Rs.60,000 - 30 days online - Meta Ads, Google Ads, Funnels, Automation, SEO, Video Editing, Design - June 2026 Batch 36
2. Generative AI Programme (AI-B9) - Rs.50,000 - 6 weeks online - Build, Automate, Scale with AI - Batch 9, limited seats

Social Eagle credibility: 10 years, 26,000+ students, 4.9/5 Google rating (1300+ reviews), Trustpilot Excellent.

CALL FLOW:
1. Open warmly: "Vanakkam! [Lead Name]-aa? Naan Priya, Social Eagle Academy-la irundhu pesuren. Oru rendu nimisham pesalama?"
2. Ask ONE question at a time about their situation
3. Pitch relevant course in 3-4 sentences
4. Handle objections naturally
5. Book Zoom meeting - collect name, phone, course interest, preferred time
6. Close warmly

OBJECTIONS:
- Price high: "First client-aye course fee cover pannidum. Installment option-um irukkum - zoom call-la discuss pannalam"
- No time: "Daily 2 hours dhaan - online, your convenience"
- Need to think: "Sure - adhanaalaye zoom call book pannalam, no pressure"
- Not genuine: "Google 1300+ reviews, 4.9 rating - check pannunga"

RULES:
- ONE question at a time
- Max 5 minute call
- Never collect payment
- Always Tanglish
- End EVERY response with the next single question or clear next step

When call is complete or lead gives all info, end your response with this JSON block:
###CALL_DATA###
{"call_outcome": "", "lead_name": "", "phone_confirmed": false, "course_interest": "", "current_situation": "", "lead_goal": "", "preferred_meeting_day": "", "preferred_meeting_time": "", "zoom_meeting_agreed": false, "objections_raised": [], "notes": ""}
###END_CALL_DATA###`;

return [{
  json: {
    systemPrompt,
    conversationHistory,
    userTranscript,
    leadName,
    courseInterest,
    callSid: callHandlerData.body?.CallSid || ''
  }
}];

// Extract GPT response text and check if call should end
const gptResponse = $input.first().json;
const context = $('Build GPT Message Context').first().json;

const fullResponse = gptResponse.choices?.[0]?.message?.content || 
                     'Oru nimisham wait pannunga...';

// Check if GPT included call data (end of call signal)
const hasCallData = fullResponse.includes('###CALL_DATA###');
let callData = null;
let speakText = fullResponse;

if (hasCallData) {
  const parts = fullResponse.split('###CALL_DATA###');
  speakText = parts[0].trim();
  const jsonPart = parts[1]?.split('###END_CALL_DATA###')?.[0]?.trim();
  try {
    callData = JSON.parse(jsonPart);
  } catch(e) {
    callData = null;
  }
}

// Update conversation history
const updatedHistory = [
  ...context.conversationHistory,
  { role: 'assistant', content: speakText }
];

// Keep history manageable - last 10 turns only
const trimmedHistory = updatedHistory.slice(-10);

return [{
  json: {
    speakText,
    callData,
    isCallEnding: hasCallData,
    updatedHistory: JSON.stringify(trimmedHistory),
    callSid: context.callSid
  }
}];

// Build Exotel TwiML-style XML response to play audio back on call
const ttsResult = $input.first().json;
const gptContext = $('Process GPT Response').first().json;

// Sarvam returns base64 audio
const audioBase64 = ttsResult.audios?.[0] || '';

// Build response for Exotel
// Exotel uses XML to control call flow
let exotelXML;

if (gptContext.isCallEnding) {
  // End the call after playing final message
  exotelXML = `<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Play>${audioBase64 ? 'data:audio/wav;base64,' + audioBase64 : ''}</Play>
  <Hangup/>
</Response>`;
} else {
  // Continue conversation - record next user response
  exotelXML = `<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Play>${audioBase64 ? 'data:audio/wav;base64,' + audioBase64 : ''}</Play>
  <Record 
    action="{{ $env.N8N_WEBHOOK_BASE_URL }}/webhook/social-eagle-call-handler"
    method="POST"
    maxLength="30"
    finishOnKey="#"
    playBeep="false"
    trim="trim-silence"
  />
</Response>`;
}

return [{
  json: {
    exotelXML,
    audioBase64,
    isCallEnding: gptContext.isCallEnding,
    callData: gptContext.callData,
    updatedHistory: gptContext.updatedHistory
  }
}];

// Save qualified lead data to Google Sheets / CRM
const buildExotelData = $('Build Exotel XML Response').first().json;
const webhookData = $('Call Handler Webhook (Exotel Streams Here)').first().json;

const callData = buildExotelData.callData || {};
const leadName = webhookData.body?.lead_name || '';
const phoneNumber = webhookData.body?.From || '';
const leadId = webhookData.body?.CustomField || '';

// Prepare final lead record
const leadRecord = {
  lead_id: leadId,
  call_timestamp: new Date().toISOString(),
  lead_name: callData.lead_name || leadName,
  phone_number: phoneNumber,
  phone_confirmed: callData.phone_confirmed || false,
  course_interest: callData.course_interest || 'Unknown',
  current_situation: callData.current_situation || 'unknown',
  lead_goal: callData.lead_goal || '',
  call_outcome: callData.call_outcome || 'completed',
  zoom_meeting_agreed: callData.zoom_meeting_agreed || false,
  preferred_meeting_day: callData.preferred_meeting_day || '',
  preferred_meeting_time: callData.preferred_meeting_time || '',
  objections_raised: (callData.objections_raised || []).join(', '),
  notes: callData.notes || '',
  needs_callback: callData.call_outcome === 'callback_requested',
  callback_time: callData.callback_time || '',
  meeting_booked: false,
  created_at: new Date().toISOString()
};

console.log('Lead data saved:', JSON.stringify(leadRecord, null, 2));

return [{ json: leadRecord }];

// Handle call status updates from Exotel
const statusData = $input.first().json.body || $input.first().json;

const callSid = statusData.CallSid || '';
const callStatus = statusData.Status || statusData.CallStatus || '';
const duration = statusData.Duration || 0;
const leadId = statusData.CustomField || '';

console.log(`Call Status Update - SID: ${callSid}, Status: ${callStatus}, Duration: ${duration}s, Lead: ${leadId}`);

// If call was not answered, flag for retry
const needsRetry = ['no-answer', 'busy', 'failed'].includes(callStatus.toLowerCase());
const retryCount = parseInt(statusData.retry_count || '0');

return [{
  json: {
    callSid,
    callStatus,
    duration: parseInt(duration),
    leadId,
    needsRetry: needsRetry && retryCount < 3,
    retryCount: retryCount + 1,
    timestamp: new Date().toISOString()
  }
}];
